-- ----------------------------
-- Table structure for cg_config
-- ----------------------------
DROP TABLE IF EXISTS `cg_config`;
CREATE TABLE `cg_config`  (
  `Id` bigint(20) NOT NULL COMMENT '主键Id',
  `AuthorName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作者姓名',
  `TablePrefix` tinyint(1) NULL DEFAULT NULL COMMENT '是否移除表前缀',
  `GenerateType` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '生成方式 1 CodeFirst 2 DbFirst',
  `DbKey` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '库定位器名',
  `DbName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '数据库名(保留字段)',
  `DbType` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '数据库类型',
  `TableName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '数据库表名',
  `Namespace` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '命名空间',
  `EntityName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '实体名称',
  `BusName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务名',
  `ApiAreaName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Api分区名称',
  `AreaGrouping` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'API区域二级分组名称',
  `BaseEntity` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '基类名称',
  `MenuPid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '/app' COMMENT '菜单编码',
  `MenuAfterText` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '菜单后缀',
  `BackendOut` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '后端输出目录',
  `FrontendOut` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '前端输出目录',
  `DbMigrateSqlOut` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '数据迁移输出目录',
  `Comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注说明',
  `Usings` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '实体导入的命令空间',
  `GenEntity` tinyint(1) NULL DEFAULT NULL COMMENT '生成Entity实体类',
  `GenRepository` tinyint(1) NULL DEFAULT NULL COMMENT '生成Repository仓储类',
  `GenService` tinyint(1) NULL DEFAULT NULL COMMENT '生成Service服务类',
  `GenAdd` tinyint(1) NULL DEFAULT NULL COMMENT '生成新增服务',
  `GenUpdate` tinyint(1) NULL DEFAULT NULL COMMENT '生成更新服务',
  `GenDelete` tinyint(1) NULL DEFAULT NULL COMMENT '新增删除服务',
  `GenGetList` tinyint(1) NULL DEFAULT NULL COMMENT '生成列表查询服务',
  `GenSoftDelete` tinyint(1) NULL DEFAULT NULL COMMENT '生成软删除服务',
  `GenBatchDelete` tinyint(1) NULL DEFAULT NULL COMMENT '生成批量删除服务',
  `GenBatchSoftDelete` tinyint(1) NULL DEFAULT NULL COMMENT '生成批量软删除服务',
  `GenViewType` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'Single' COMMENT '生成界面类型，单表/主子表',
  `ProId` bigint(20) NULL DEFAULT NULL COMMENT '创建者Id',
  `ProName` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者姓名',
  `ProTime` datetime NOT NULL COMMENT '创建时间',
  `ModId` bigint(20) NULL DEFAULT NULL COMMENT '修改者Id',
  `ModName` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改者姓名',
  `ModTime` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `IsModified` tinyint(1) NOT NULL DEFAULT 0 COMMENT '已修改',
  `IsDeleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '已删除',
  PRIMARY KEY (`Id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

