  `Suggestion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '建议解释',
  `FirstAuditTime` datetime NULL DEFAULT NULL COMMENT '初审时间',
  `SecondAuditTime` datetime NULL DEFAULT NULL COMMENT '复审时间',
  `CreateReportTime` datetime NULL DEFAULT NULL COMMENT '报告时间',
  `ReviewCount` int(4) NULL DEFAULT 0 COMMENT '审核次数',
  `TestType` int(11) NOT NULL DEFAULT 0 COMMENT '检查类型 0默认1加做 2复查',
  `IsPdfReport` tinyint(2) NOT NULL DEFAULT 0 COMMENT 'PDF报告',
  `EntrustHospitalCode` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '委托医院代码',
  `EntrustHospitalName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '委托医院名称',
  `EntrustStatus` int(1) NULL DEFAULT 0 COMMENT '委托状态',
  `IsExceptionResult` int(11) NOT NULL DEFAULT 0 COMMENT '异常结果',
  `PrintReportTime` datetime NULL DEFAULT NULL COMMENT '打印时间',
  `DownloadFlag` int(11) NULL DEFAULT NULL COMMENT '下载结果标志',
  `StorageStatus` int(11) NULL DEFAULT NULL COMMENT '入库状态',
  `StorageLocation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '入库位置',
  `InternalRemarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '内注',
  `ProId` bigint(20) NULL DEFAULT NULL COMMENT '创建者Id',
  `ProName` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者姓名',
  `ProTime` datetime NOT NULL COMMENT '创建时间',
  `ModId` bigint(20) NULL DEFAULT NULL COMMENT '修改者Id',
  `ModName` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改者姓名',
  `ModTime` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `IsModified` tinyint(1) NOT NULL DEFAULT 0 COMMENT '已修改',
  `IsDeleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '已删除',
  PRIMARY KEY (`Id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

