DROP TABLE IF EXISTS `exam_result`;
CREATE TABLE `exam_result`  (
  `Id` bigint(20) NOT NULL COMMENT '主键Id',
  `TenantId` bigint(20) NOT NULL COMMENT '租户Id',
  `TaskDetailId` bigint(20) NULL DEFAULT NULL,
  `ExamInfoId` bigint(20) NULL DEFAULT NULL,
  `GroupCode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '组别代码',
  `GroupName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '组别名称',
  `Barcode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '条码',
  `SampleNo` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '样本号',
  `TestDate` date NULL DEFAULT NULL COMMENT '检测日期',
  `ComboCode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '套餐代码',
  `PurCode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '目的代码',
  `PurName` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '目的名称',
  `InstrumentItemCode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '上机项目代码',
  `ItemCode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '项目代码',
  `ItemName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '项目名称',
  `ItemNamePersonalize` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '个性化项目名称',
  `ItemNameEN` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '英文名称',
  `ItemNameAB` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '项目简称',
  `ItemUnit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '项目单位',
  `ItemResult` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '检验结果',
  `HLFlag` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '高低标记',
  `ItemReference` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '参考范围',
  `WarningRange` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '警告值范围',
  `CriticalRange` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '危急值范围',
  `DisplayRange` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '报告显示范围',
  `ReagentCode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '试剂代码',
  `ReagentName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '试剂名称',
  `InstrumentCode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '仪器代码',
  `InstrumentName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '仪器名称',
  `MethodCode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '方法学代码',
  `MethodName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '方法学',
  `ResultSource` int(11) NULL DEFAULT NULL COMMENT '结果来源1输入 2回传',
  `OriginalValue` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '原始结果',
  `IsReportShow` tinyint(4) NULL DEFAULT NULL COMMENT '报告显示',
  `ReportOrder` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '排序',
  `MethodBasis` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '方法依据',
  `CutOffValue` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'cutoff值',
  `ODValue` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'od值',
  `SpecificValue` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 's/co',
  `ResultType` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '结果类型，定量、定性等',
  `IsCalculate` tinyint(1) NULL DEFAULT NULL COMMENT '是否计算项0否1是',
  `CalcExpression` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用计算公式',
  `InTestCount` int(11) NULL DEFAULT NULL COMMENT '上机次数',
  `EntrustStatus` int(11) NULL DEFAULT NULL COMMENT '委托状态',
  `AddType` int(11) NULL DEFAULT NULL COMMENT '增项',
  `ReviewStatus` int(11) NULL DEFAULT 0 COMMENT '复查',
  `ProTime` datetime NOT NULL COMMENT '创建时间',
  `ProId` bigint(20) NULL DEFAULT NULL COMMENT '创建者Id',
  `ProName` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者姓名',
  `ModId` bigint(20) NULL DEFAULT NULL COMMENT '修改者Id',
  `ModName` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '修改者姓名',
  `ModTime` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `IsModified` tinyint(1) NOT NULL DEFAULT 0 COMMENT '已修改',
  `IsDeleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '已删除',
  PRIMARY KEY (`Id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

