  `EntrustHospitalName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '委托医院名称',
  `EntrustStatus` int(1) NULL DEFAULT 0 COMMENT '委托状态',
  `EntrustConfirmId` bigint(20) NULL DEFAULT NULL COMMENT '委托确认人Id',
  `EntrustConfirmName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '委托确认人',
  `EntrustConfirmTime` datetime NULL DEFAULT NULL COMMENT '委托确认时间',
