  `EstimateAskTime` datetime NULL DEFAULT NULL COMMENT '预计问询时间',
  `ReceiveTime` datetime NULL DEFAULT NULL COMMENT '接收时间',
  `HandoverStatus` int(11) NULL DEFAULT 0 COMMENT '交接状态',
  `HandoverId` bigint(20) NULL DEFAULT NULL COMMENT '交接人Id',
  `HandoverName` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '交接人',
  `HandoverTime` datetime NULL DEFAULT NULL COMMENT '交接时间',
  `HandoverBatchNo` bigint(20) NULL DEFAULT NULL COMMENT '交接批次',
  `Sort` int(11) NOT NULL COMMENT '排序',
  `ApplyPurposeIds` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '申请目的Id',
  `ProId` bigint(20) NULL DEFAULT NULL COMMENT '创建者Id',
  `ProName` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者姓名',
  `ProTime` datetime NOT NULL COMMENT '创建时间',
