-- ----------------------------
-- Procedure structure for PR_GetSequence
-- ----------------------------
DROP PROCEDURE IF EXISTS `PR_GetSequence`;
delimiter ;;
CREATE PROCEDURE `PR_GetSequence`(IN i_Date DATETIME,-- 输入日期时间 (格式: YYYY-MM-DD HH:MM:SS)
  IN i_SequenceCode VARCHAR ( 50 ),-- 序列代码
  IN i_TenantId BIGINT,
  IN i_OperId BIGINT,
  IN i_OperName VARCHAR ( 32 ),
  IN i_IsTest INT,
  OUT o_SeqVal VARCHAR ( 100 ),-- 生成的序列值
  OUT o_Code INT,
  OUT o_ErrMsg VARCHAR ( 128 ))
BEGIN
  DECLARE
    v_Prefix VARCHAR ( 20 );
  DECLARE
    v_StartNo INT;
  DECLARE
    v_Step INT;
  DECLARE
    v_Length INT;
  DECLARE
    v_Char CHAR ( 1 );
  DECLARE
    v_Suffix VARCHAR ( 20 );
  DECLARE
    v_ResetType VARCHAR ( 10 );
  DECLARE
    v_ResetTime TIME;
  DECLARE
    v_Week INT;
  DECLARE
    v_CurrentVal INT;
  DECLARE
    v_CurrentResetVal VARCHAR ( 20 );
  DECLARE
    v_NeedReset BOOLEAN DEFAULT FALSE;
  DECLARE
    v_ResetVal VARCHAR ( 20 );-- 获取序列配置
  DECLARE error_code CHAR(5) DEFAULT '00000';
  DECLARE error_message TEXT;
    
DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
        -- 获取错误信息
        GET DIAGNOSTICS CONDITION 1
            error_code = RETURNED_SQLSTATE,
            error_message = MESSAGE_TEXT;
            
        Set o_ErrMsg = CONCAT('错误代码: ', error_code, ', 错误信息: ', error_message);
        Set o_Code = -1;
        SELECT o_ErrMsg AS error_detail;
        ROLLBACK;
  END;
  
START TRANSACTION;

Select Perfix,
       StartNo,
       SequenceStep,
       CompletionLength,
       CompletionChar,
       Suffix,
       ResetType,
       ResetTime
  Into v_Prefix,
       v_StartNo,
       v_Step,
       v_Length,
       v_Char,
       v_Suffix,
       v_ResetType,
       v_ResetTime
  From base_sequence
 Where SequenceCode = i_SequenceCode And TenantId = i_TenantId; -- 如果没有找到序列配置
If v_StartNo Is Null Then

  Set o_SeqVal = Null;
  SIGNAL SQLSTATE '45000' Set MESSAGE_TEXT = 'sequence config not found';

End If; -- 计算当前重置标识
Case v_ResetType
  When '101' Then
    -- 检查是否超过当日重置时间
    /*If Time(i_Date) >= v_ResetTime Then
    
      Set v_ResetVal = DATE_FORMAT(i_Date, '%Y-%m-%d');
    Else
      -- Set v_ResetVal = DATE_FORMAT(i_Date - Interval 1 Day, '%Y-%m-%d');
      Set v_ResetVal = DATE_FORMAT(i_Date, '%Y-%m-%d');
    
    End If;*/
    Set v_ResetVal = DATE_FORMAT(i_Date, '%Y-%m-%d');
  When '102' Then
    Select DAYOFWEEK(i_Date) Into v_Week;
    If v_Week = 1 Then
    
      Set v_Week = 7;
    Else
      Set v_Week = v_Week - 1;
    
    End If;
    Select v_Week;
  
  When '103' Then
    -- 检查是否是当月第一天
    If Day(i_Date) = 1 Then
    
      Set v_ResetVal = DATE_FORMAT(i_Date, '%Y-%m');
    Else
      Set v_ResetVal = DATE_FORMAT(i_Date, '%Y-%m');
    
    End If;
  
  When '104' Then
    -- 检查是否是1月1日
    If Month(i_Date) = 1 And Day(i_Date) = 1 Then
      Set v_ResetVal = Year(i_Date);
    Else
      Set v_ResetVal = Year(i_Date);
    
    End If;
  Else
    Set v_ResetVal = 'PERMANENT'; -- 永久不重置

End Case; -- 检查是否需要重置

Select CurrentVal, ResetVal
  Into v_CurrentVal, v_CurrentResetVal
  From base_sequence_current
 Where SequenceCode = i_SequenceCode And TenantId = i_TenantId And ResetVal = v_ResetVal
   For Update;

If v_CurrentVal Is Null Then
  -- 无记录
  Set v_NeedReset = True;
  /*ELSEIF v_ResetVal != v_CurrentResetVal Then 
  -- 重置周期变化
  Set v_NeedReset = True;*/
End If; 

-- 处理序列值
If v_NeedReset Then
  -- 重置序列
  Set v_CurrentVal = v_StartNo;
  If i_IsTest = 0 Then
    -- 插入或更新当前序列记录
       TenantId,
       SequenceCode,
       ResetVal,
       CurrentVal,
       ProId,
       ProName,
       ProTime)
    Values
      (UUID(),
       i_TenantId,
       i_SequenceCode,
       v_ResetVal,
       v_StartNo + v_Step,
       i_OperId,
       i_OperName,
       NOW()) On DUPLICATE KEY Update CurrentVal = v_StartNo + v_Step, ResetVal = v_ResetVal;
  
  End If;

  Set o_SeqVal = CONCAT(ifnull(v_Prefix, ''),
                        LPAD(v_CurrentVal, v_Length, v_Char),
                        ifnull(v_Suffix, ''));
  Set o_Code = 1;
Else
  If i_IsTest = 0 Then
    -- 正常递增序列
    Update base_sequence_current
       Set CurrentVal = CurrentVal + v_Step
     Where SequenceCode = i_SequenceCode And TenantId = i_TenantId And ResetVal = v_ResetVal;
  
  End If;
  Set o_SeqVal = CONCAT(ifnull(v_Prefix, ''),
                        LPAD(v_CurrentVal, v_Length, v_Char),
                        ifnull(v_Suffix, ''));
  Set o_Code = 1;
End If;

COMMIT;

End
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
